NOW = datetime(2026, 10, 2, 20, 0, tzinfo=timezone.utc)
STAMP = "2026-10-02T19:59:00Z"
RUN = "12345"
RUN_ATTEMPT = "2"
CLIENTS = {name: {"package": package, "version": "2026.1.0-rc.3",
                  "integrity": "sha512-hand-built", "digest": None, "sourceSha": "a" * 40}
           for name, package in (("honua-sdk-js", "@honua/sdk"),
                                 ("honua-mcp-server", "@honua/mcp-server"))}
MANIFEST = {"platformRelease": "2026.1-rc.3", "clientArtifacts": CLIENTS,
            "components": {"honua-server": {"sha": "b" * 40,
                            "image": "ghcr.io/honua/server", "digest": "sha256:" + "c" * 64}}}
# Number, stage, command are written independently from the owned journey contract.
STAGES = [
    (1, "installed-client-handoff", "install exact manifest clients; verify readiness, identity, auth, profiles and tools/list"),
    (2, "credential-preflight", "honua admin apiKeys list/effective-permissions"),
    (3, "publish-service", "honua admin connection create/test; import; publish/configure layer and access policy"),
    (4, "style-render", "honua_get_style; honua_apply_style_preset; honua_render_map; validate decoded PNG"),
    (5, "bounded-gp", "discover/run geometry.buffer; wait/cancel canonical job; retain result"),
    (6, "durable-compositions", "create/mutate/validate/version map+dashboard; restart/reopen; compare hashes"),
    (7, "publication-proposal", "submit and poll durable AwaitingApproval proposal bound to item/version/hash"),
    (8, "separate-principal-approval", "honua admin operate approveOperationProposal --profile approver --yes; poll published URL"),
]


def receipt(cell):
    return {"schemaVersion": 1, "receiptSchema": "terminal-journey-receipt-v1",
            "evidenceKey": "release.e2e.terminal-zero-to-map", "generatedAt": STAMP,
            "mode": "live", "target": {"id": cell, "kind": "aws-ecs",
                "configPath": "target.json", "configSha256": "d" * 64},
            "status": "pass", "release": "2026.1-rc.3", "clientArtifacts": CLIENTS,
            "clientWorkspace": {"status": "pass", "source": "published-registry-bytes",
                "resolved": [{"name": "honua-sdk-js", "package": "@honua/sdk",
                              "version": "2026.1.0-rc.3", "ecosystem": "npm",
                              "integrityVerified": True, "tarballSha256": "e" * 64,
                              "bin": {"honua": "cli.js"}}],
                "commandSurface": [], "installNotes": []},
            "server": {"sourceSha": "b" * 40, "image": "ghcr.io/honua/server@sha256:" + "c" * 64},
            "fixtureRevision": "fixture-v1", "configRevision": "config-v1",
            "authPolicyRevision": "auth-v1", "roster": {"status": "pass"},
            "stages": [{"number": number, "stage": stage, "command": command,
                "status": "pass", "blockedBy": [],
                "checks": [{"id": "probe", "kind": "mcp-tool", "invocation": command,
                            "status": "pass", "detail": "observed"}],
                "operationId": "op", "operationInstanceId": "opinst", "correlationId": "corr",
                "auditId": "audit", "proposalId": "proposal", "jobId": "job", "resourceUri": "honua://jobs/job",
                "jobStatus": "accepted", "jobCreatedAt": STAMP, "policyDecisionId": None, "approvalId": None,
                "actuatorId": None, "verificationId": None,
                "evidence": {"uri": "urn:hand-built:observation", "source": "live-aws-ecs",
                             "freshness": "verified-current", "completeness": "complete",
                             "observedAt": STAMP}} for number, stage, command in STAGES],
            "notices": [], "linkedEvidence": {"awsProvisioning": "honua-release#129",
                                               "genuineModelCanary": "honua-release#161"}}


def failed_receipt(cell):
    result = receipt(cell)
    result["status"] = "fail"
    result["stages"][0]["status"] = "fail"
    result["stages"][0]["checks"][0]["status"] = "fail"
    result["failure"] = {"number": 1, "stage": STAGES[0][1], "command": STAGES[0][2],
                         "check": "probe", "detail": "failed handoff"}
    return result


class Intake:
    def __init__(self, root):
        self.root = root
        self.candidate = root / "candidate.yaml"
        self.candidate.write_text(yaml.safe_dump(MANIFEST))
        self.digest = hashlib.sha256(self.candidate.read_bytes()).hexdigest()
        for cell in checker.GA_CELLS:
            self.write(cell)

    def directory(self, cell):
        return self.root / ("e2e-cloud-aws-gate-report-" + cell.replace("/", "-"))

    def write(self, cell, receipts=None, *, drivers=None, attributions=None):
        directory = self.directory(cell)
        directory.mkdir(exist_ok=True)
        attempts = []
        for i, value in enumerate(receipts or [receipt(cell)], 1):
            path = directory / "cloud-evidence" / RUN / RUN_ATTEMPT / cell / f"receipt-{i}.json"
            path.parent.mkdir(parents=True, exist_ok=True)
            path.write_text(json.dumps(value))
            record = {"number": i, "cell": cell, "runId": RUN, "runAttempt": RUN_ATTEMPT,
                      "candidateDigest": self.digest, "receipt": str(path.relative_to(directory)),
                      "receiptSha256": hashlib.sha256(path.read_bytes()).hexdigest(),
                      "failureAttribution": (attributions[i-1] if attributions else
                                             "infrastructure" if value["status"] != "pass" else None)}
            if drivers:
                record["driver"] = drivers[i-1]
            attempts.append(record)
        report = {"cell": cell, "status": "pass", "journeyAttempts": attempts}
        self.save(cell, report)
        return report

    def save(self, cell, report):
        (self.directory(cell) / "gate-report-cloud.json").write_text(json.dumps(report))

    def evaluate(self):
        return checker.evaluate(self.root, self.candidate, self.digest, RUN, RUN_ATTEMPT, at=NOW)


@pytest.fixture
def intake(tmp_path):
    return Intake(tmp_path)


def assert_red(intake, reason):
    report = intake.evaluate()
    assert report["status"] == report["overallStatus"] == "fail"
    assert reason in report["why"]


def test_hand_built_fixtures_validate_against_owned_schema():
    validator = Draft202012Validator(checker.load_json(checker.ROOT /
        "certification/terminal-journey/receipt.schema.json"), format_checker=FormatChecker())
    for cell in checker.GA_CELLS:
        validator.validate(receipt(cell))
        validator.validate(failed_receipt(cell))


def test_all_four_exact_candidate_cells_pass_and_record_driver(intake):
    intake.write(checker.GA_CELLS[0], drivers=["genuine-model"])
    result = intake.evaluate()
    assert result["status"] == "pass"
    ga = [r for r in result["cells"] if r["counted"]]
    assert len(ga) == 4
    assert ga[0]["drivers"] == ["genuine-model"]
    assert ga[0]["attempts"][0]["completedAt"] == STAMP
    assert ga[1]["drivers"] == ["deterministic"]
    assert result["gates"][0]["decided"] == "pass"


@pytest.mark.parametrize("attribution", ["model", "infrastructure"])
def test_attributed_failure_then_second_attempt_passes(intake, attribution):
    cell = checker.GA_CELLS[0]
    intake.write(cell, [failed_receipt(cell), receipt(cell)], attributions=[attribution, None])
    result = intake.evaluate()
    assert result["status"] == "pass"
    assert result["cells"][0]["attempts"][0]["failureAttribution"] == attribution


