@pytest.mark.parametrize("defect", ["stage", "check", "freshness", "completeness", "observedAt", "source", "roster", "mode"])
def test_nonobserved_or_incomplete_journey_is_red(intake, defect):
    cell = checker.GA_CELLS[0]
    data = receipt(cell)
    stage = data["stages"][0]
    if defect == "stage":
        data["stages"].pop()
    elif defect == "check":
        stage["checks"] = []
    elif defect == "roster":
        data["roster"]["status"] = "blocked"
    elif defect == "mode":
        data["mode"] = "build"
    else:
        stage["evidence"][defect] = {"freshness": "stale", "completeness": "partial",
            "observedAt": "2026-09-30T19:59:00Z", "source": "live-local-docker"}[defect]
    intake.write(cell, [data])
    assert intake.evaluate()["status"] == "fail"


