@pytest.mark.parametrize("defect", ["missing", "hash", "escape", "absolute", "symlink", "malformed"])
def test_untrusted_receipt_file_is_red(intake, defect, tmp_path):
    cell = checker.GA_CELLS[0]
    report = intake.write(cell)
    record = report["journeyAttempts"][0]
    path = intake.directory(cell) / record["receipt"]
    if defect == "missing":
        path.unlink()
    elif defect == "hash":
        record["receiptSha256"] = "0" * 64
    elif defect == "escape":
        record["receipt"] = "../receipt.json"
    elif defect == "absolute":
        record["receipt"] = str(path)
    elif defect == "symlink":
        outside = tmp_path / "outside.json"
        outside.write_bytes(path.read_bytes())
        path.unlink()
        path.symlink_to(outside)
    else:
        path.write_text('{"bad": true, "bad": false}')
        record["receiptSha256"] = hashlib.sha256(path.read_bytes()).hexdigest()
    intake.save(cell, report)
    assert intake.evaluate()["status"] == "fail"


