@pytest.mark.parametrize("status", ["pass", "fail", "blocked", "skipped", "corrupt"])
def test_preview_never_blocks_or_counts(intake, status):
    for cell in checker.PREVIEW_CELLS:
        report = intake.write(cell)
        report["status"] = status
        intake.save(cell, report)
        if status == "corrupt":
            (intake.directory(cell) / "gate-report-cloud.json").write_text("{invalid")
    result = intake.evaluate()
    assert result["status"] == "pass"
    preview = [r for r in result["cells"] if r["evidenceTier"] == "Preview"]
    assert len(preview) == 4 and not any(r["counted"] for r in preview)


